uint64_t warpSignature(const Sample&s,const Clip&c,const TempoMap&clock){uint64_t h=1469598103934665603ull;auto add=[&](double x){uint64_t v;memcpy(&v,&x,8);h^=v;h*=1099511628211ull;};add((double)(uintptr_t)&s);add((double)(uintptr_t)s.identity.get());add(s.left.size());add(c.beat);add(c.length);add(c.offset);add(c.warpBpm);add(c.warpReferenceOffset);if(c.warpReference){add((double)(uintptr_t)c.warpReference.get());add((double)(uintptr_t)c.warpReference->identity.get());}for(auto&p:c.warpPoints){add(p.beat);add(p.second);}double b=c.beat;for(int i=0;i<3074;i++){add(b);add(clock.bpmAt(b));double next=clock.nextChange(b);if(next>=c.beat+c.length)break;b=next;}return h;}
std::shared_ptr<Sample>renderWarp(const Sample&s,const Clip&c,const TempoMap&clock){
    if(!c.warp)return std::make_shared<Sample>(s);if(s.left.size()!=s.right.size()||s.rate<8000||c.length<=0||c.warpBpm<10||c.warpBpm>999||c.warpPoints.size()>256)throw std::runtime_error("Invalid Warp source");
    uint64_t key=warpSignature(s,c,clock);if(c.warpAudio&&c.warpKey==key)return c.warpAudio;
    struct Cache {uint64_t key;std::weak_ptr<const uint8_t>source;std::weak_ptr<Sample>audio;};static std::mutex mutex;static std::vector<Cache>cache;
    {std::lock_guard<std::mutex>lock(mutex);for(auto i=cache.begin();i!=cache.end();){auto audio=i->audio.lock();if(!audio)i=cache.erase(i);else{if(i->key==key&&i->source.lock()==s.identity)return audio;++i;}}}
    double available=s.left.size()/double(s.rate)-c.offset;if(available<=0)throw std::runtime_error("Warp offset exceeds the source");std::vector<WarpPoint>points=c.warpPoints;
    if(points.empty())points={{0,c.offset},{c.length,c.offset+std::min(available,c.length*60/c.warpBpm)}};
    if(points.size()<2||std::abs(points.front().beat)>1e-7||std::abs(points.back().beat-c.length)>1e-7)throw std::runtime_error("Warp needs start and end markers");
    for(size_t i=0;i<points.size();i++){auto&p=points[i];if(!std::isfinite(p.beat)||!std::isfinite(p.second)||p.beat<0||p.second<0||p.second>s.left.size()/double(s.rate)+1e-7||(i&&(p.beat<=points[i-1].beat||p.second<=points[i-1].second)))throw std::runtime_error("Warp markers must stay in source and timeline order");}
    if(c.warpReference&&(c.warpReference->rate!=s.rate||!std::isfinite(c.warpReferenceOffset)))throw std::runtime_error("Invalid linked Warp reference");double total=clock.duration(c.beat,c.beat+c.length);if(total<=0||total>600)throw std::runtime_error("Warp supports clips up to ten minutes");auto out=std::make_shared<Sample>();out->rate=s.rate;size_t count=(size_t)std::llround(total*s.rate);if(count>64ull*1024*1024)throw std::runtime_error("Warp cache exceeds 512 MB; split this clip first");out->left.resize(count);out->right.resize(count);
    // Split at both Warp anchors and tempo changes. Existing stereo-linked WSOLA preserves pitch.
    std::vector<double>cuts{0,c.length};for(auto&p:points)cuts.push_back(p.beat);for(double b=clock.nextChange(c.beat);b<c.beat+c.length;b=clock.nextChange(b))cuts.push_back(b-c.beat);std::sort(cuts.begin(),cuts.end());cuts.erase(std::unique(cuts.begin(),cuts.end()),cuts.end());
    auto sourceAt=[&](double b){auto next=std::upper_bound(points.begin(),points.end(),b,[](double b,auto&p){return b<p.beat;});if(next==points.end())return points.back().second;if(next==points.begin())return next->second;auto prev=next-1;return prev->second+(next->second-prev->second)*(b-prev->beat)/(next->beat-prev->beat);};
    for(size_t k=1;k<cuts.size();k++){size_t first=(size_t)std::llround(sourceAt(cuts[k-1])*s.rate),last=std::min(s.left.size(),(size_t)std::llround(sourceAt(cuts[k])*s.rate));size_t at=(size_t)std::llround(clock.duration(c.beat,c.beat+cuts[k-1])*s.rate),end=std::min(count,(size_t)std::llround(clock.duration(c.beat,c.beat+cuts[k])*s.rate));if(last<=first||end<=at)continue;double ratio=(end-at)/double(last-first);if(ratio<.25||ratio>4)throw std::runtime_error("Warp stretch ratio must be between 0.25x and 4x");auto actual=extractSample(s,first,last);std::shared_ptr<Sample>guide;if(c.warpReference){int64_t delta=std::llround(c.warpReferenceOffset*s.rate),begin=(int64_t)first+delta,finish=(int64_t)last+delta;if(begin<0||finish>(int64_t)c.warpReference->left.size())throw std::runtime_error("Linked Warp markers exceed the reference recording");guide=extractSample(*c.warpReference,(size_t)begin,(size_t)finish);}auto piece=stretchSample(*actual,ratio,guide.get());size_t n=std::min(end-at,piece->left.size());std::copy_n(piece->left.data(),n,out->left.data()+at);std::copy_n(piece->right.data(),n,out->right.data()+at);if(at&&n){size_t fade=std::min<size_t>({64,at,n});float left=out->left[at-1],right=out->right[at-1];for(size_t j=0;j<fade;j++){float mix=(j+1)/float(fade);out->left[at+j]=left*(1-mix)+out->left[at+j]*mix;out->right[at+j]=right*(1-mix)+out->right[at+j]*mix;}}}
    {std::lock_guard<std::mutex>lock(mutex);if(cache.size()<128)cache.push_back({key,s.identity,out});}return out;
}
